// Owner workspace UI. All requests use the server-enforced marketing namespace.
'use strict';
window.MarketingScanner = (() => {
  const tabIds=['pipeline','leads','rules','sources','discovery','history','conversations','sender'];
  function savedTab(){try{const value=sessionStorage.getItem('marketingScannerTab');return tabIds.includes(value)?value:'pipeline';}catch{return 'pipeline';}}
  let lastPaint='', snapshot=null, tab=savedTab(), editing=null, dialogs=[], loading=false, failure='', previewResult='', previewDraft={ruleId:'',text:''}, leadTopic='all', leadStatus='new', leadContact='telegram_author', leadOffset=0;
  function selectTab(value){if(!tabIds.includes(value))return;tab=value;try{sessionStorage.setItem('marketingScannerTab',value);}catch{}}
  const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(text,action,id='',kind='secondary')=>`<button type="button" class="button ${kind}" data-m-action="${action}" data-id="${h(id)}">${h(text)}</button>`;
  const input=(label,name,type='text',value='',extra='')=>`<label class="ls-field">${h(label)}<input name="${name}" type="${type}" value="${h(value)}" ${extra}></label>`;
  const area=(label,name,value='',placeholder='')=>`<label class="ls-field">${h(label)}<textarea name="${name}" rows="4" maxlength="8000" placeholder="${h(placeholder)}">${h(value)}</textarea></label>`;
  const stamp=v=>v?new Date(v).toLocaleString('ru-RU'):'Ещё не было';
  const statusNames={not_connected:'Нет общего подключения',connected:'Общее подключение работает'};
  async function api(path,body,timeoutMs=45000){
    const response=await fetch('/api/scanner/marketing/'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Scanner-Request':'1'},signal:AbortSignal.timeout(timeoutMs),...(body!==undefined?{body:JSON.stringify(body)}:{})});
    let data;try{data=await response.json();}catch{throw Error(response.status===502?'Служба запускается. Повторите через несколько секунд.':'Сервер недоступен. Проверьте соединение.');}
    if(!response.ok){const error=Error(typeof data.detail==='string'?data.detail:'Проверьте заполнение полей.');error.status=response.status;throw error;}
    return data;
  }
  function view(){return '<div id="marketing-scanner"><div class="empty"><strong>Загружаем лидсканер…</strong>Подключаемся к серверу</div></div>';}
  const independentTab=()=>['pipeline','conversations','sender'].includes(tab);
  async function mount(){
    // Independent owner modules load their own bounded API; legacy state cannot gate them.
    draw();
    if(independentTab())return;
    if(loading)return;
    await refresh(false);
  }
  const statePath=()=> 'state?'+new URLSearchParams({status:leadStatus,topic:leadTopic==='all'?'0':leadTopic,offset:String(leadOffset),contact:leadContact});
  let refreshVersion=0;
  async function refresh(force=true){
    const version=++refreshVersion;loading=true;
    try{
      const next=await api(statePath(),undefined,15000);if(version!==refreshVersion)return;
      snapshot=next;leadOffset=next.offset??leadOffset;failure='';
    }catch(e){if(version===refreshVersion){failure=e.message;if([401,403].includes(e.status))snapshot=null;}}
    finally{if(version===refreshVersion){loading=false;const signature=JSON.stringify([snapshot,failure]);const editingField=document.activeElement?.matches('input,select,textarea');if(!independentTab()&&!contactHistoryOpen()&&(force||failure||(!editingField&&signature!==lastPaint))){lastPaint=signature;draw();}}}
  }
  function scanSummary(s){
    const health=s.scan_health;if(!health)return '';
    const cycle=health.cycle||{};
    const states={reading:'Читаем источники',completed:'Проход завершён',partial:'Есть ошибки источников',telegram_pause:'Пауза Telegram',stopped:'Поиск остановлен',account_changed:'Аккаунт изменился'};
    return `<div class="notice"><strong>Свежесть поиска</strong><br>Последняя успешная проверка источника: ${h(stamp(health.latest_source_success))}. Самая ранняя из последних проверок: ${h(stamp(health.oldest_source_success))}. Время — в часовом поясе устройства.<br>${h(states[cycle.state]||'Ожидаем первый проход')}${cycle.finished?' · '+h(stamp(cycle.finished)):''} · проверено ${cycle.checked||0}, совпадений ${cycle.matched||0}, сохранено ${cycle.saved||0}, повторов ${cycle.duplicate||0}.<br>Без ключевых слов: ${cycle.no_keywords||0}; нет намерения заказать: ${cycle.no_intent||0}; исключены правилами: ${cycle.excluded||0}; без текста или исходящие: ${cycle.skipped||0}.${s.requested_running&&health.task_alive===false?'<p class="ls-error">Рабочий цикл не запущен. Обновите панель; если состояние сохраняется, нужна проверка сервера.</p>':''}</div>`;
  }
  let contactDialog=null,contactHistoryId=0,contactHistoryRequest=0;
  function contactHistoryOpen(){return Boolean(contactDialog?.open);}
  function dialogShell(lead){
    return `<div class="panel-head"><h2 id="contact-history-title">История проверки контакта</h2><button type="button" class="button secondary" data-m-action="contact-history-close" aria-label="Закрыть историю проверки">Закрыть</button></div><p>${h(lead?.source_title||'Находка')} · ${h(lead?.author||'Автор не указан')}</p><p class="small muted">Дата публикации: ${h(stamp(lead?.created))}. Время — в часовом поясе устройства.</p><div id="contact-history-content" role="status" aria-live="polite">Загружаем проверки…</div>`;
  }
  async function showContactHistory(id){
    if(!contactDialog){
      contactDialog=document.createElement('dialog');contactDialog.id='contact-history-dialog';
      contactDialog.setAttribute('aria-labelledby','contact-history-title');
      contactDialog.style.cssText='width:min(640px,calc(100vw - 32px));max-height:85vh;overflow:auto;border:1px solid #d8e4e8;border-radius:12px;padding:24px;background:#fff;color:#173f50;';
      document.body.append(contactDialog);
      contactDialog.addEventListener('close',()=>{contactHistoryRequest++;});
    }
    contactHistoryId=id;contactDialog.innerHTML=dialogShell(snapshot?.leads.find(l=>l.id===id));
    if(!contactDialog.open)contactDialog.showModal();
    const version=++contactHistoryRequest;
    try{
      const result=await api('contact-review/'+id+'/history',undefined,15000);
      if(version!==contactHistoryRequest||!contactDialog.open)return;
      const names={telegram_author:'Личный автор Telegram',missing_contact:'Личный контакт не подтверждён',marketplace_task:'Заказ на бирже',contacted_dialogue:'Ранее начатая переписка'};
      const rows=result.history||[];
      contactDialog.querySelector('#contact-history-content').innerHTML=rows.length?rows.map(row=>`<section class="notice"><strong>${h(names[row.kind]||'Проверка контакта')}</strong><p>${h(row.reason)}</p><p class="small muted">Проверено: ${h(stamp(row.assessed))}${row.contact_username?' · @'+h(row.contact_username):''}</p></section>`).join(''):'<p>Сохранённых проверок пока нет.</p>';
    }catch(error){
      if(version!==contactHistoryRequest||!contactDialog.open)return;
      contactDialog.querySelector('#contact-history-content').innerHTML=`<p class="ls-error" role="alert">${h(error.message)}</p>${button('Повторить','contact-history-retry',id)}`;
    }
  }
  function tabNavigation(){return `<nav class="ls-tabs" aria-label="Разделы лидсканера">${[['pipeline','Лиды → оплата'],['leads','Находки'],['conversations','Переписка'],['rules','Поиски'],['sources','Источники'],['discovery','Парсер групп'],['history','Анализ истории'],['sender','Мой Telegram']].map(([id,label])=>`<button type="button" class="${tab===id?'active':''}" data-m-action="tab" data-id="${id}" aria-current="${tab===id?'page':'false'}">${label}</button>`).join('')}</nav>`;}
  function ownerShell(){return `<div class="page-heading"><div><h1>Маркетинг · SignM</h1><p>Запросы на сайты, SEO, Директ, SMM и автоматизацию · Дубай · русский и английский</p></div></div><div class="notice">Чтение источников использует общий Telegram-аккаунт сервиса; лимиты и доступность чтения общие. Личная переписка ведётся через отдельно подключённый @demo_identity_3.</div>${tabNavigation()}`;}
  function draw(){
    const root=document.querySelector('#marketing-scanner');if(!root)return;
    if(independentTab()){
      root.innerHTML=ownerShell()+(tab==='pipeline'?window.SignMPipeline.view():tab==='conversations'?window.OwnerInbox.view():window.OwnerSenderPanel.view())+'<p class="ls-footnote">Личный раздел владельца. Статус поиска и управление источниками — на вкладках «Находки», «Поиски» и «Источники».</p>';
      if(tab==='pipeline')window.SignMPipeline.mount({openConversation:openPipelineConversation});
      if(tab==='conversations')window.OwnerInbox.mount();
      if(tab==='sender')window.OwnerSenderPanel.mount();
      return;
    }
    if(!snapshot){root.innerHTML=ownerShell()+(failure?`<div class="ls-error" role="alert">${h(failure)}</div>${button('Повторить','refresh')}`:'<div class="empty"><strong>Загружаем выбранный раздел…</strong></div>');return;}
    const s=snapshot;
    root.innerHTML=`<div class="page-heading"><div><h1>Маркетинг · SignM</h1><p>Запросы на сайты, SEO, Директ, SMM и автоматизацию · Дубай · русский и английский</p></div><div class="heading-actions"><a class="button secondary" href="/api/scanner/marketing/export" download>Скачать находки CSV</a>${button('Обновить','refresh')}${button(s.running?'Остановить поиск':'Запустить поиск','running','',s.running?'secondary':'')}</div></div>
      <div class="ls-status"><span class="badge ${s.connection==='connected'?'green':'amber'}">Telegram: ${h(statusNames[s.connection]||s.connection)}</span><strong>${s.running?'Поиск включён':'Поиск остановлен'}</strong><span>${s.sources.filter(x=>x.enabled).length} источников · ${s.rules.filter(x=>x.enabled).length} из ${s.rules.length} поисков включено · ${s.total} находок</span></div>
      ${scanSummary(s)}${s.retry_at*1000>Date.now()?`<div class="notice amber">Следующая проверка после ${h(stamp(s.retry_at*1000))}. Поиск продолжится автоматически.</div>`:''}${failure?`<div class="ls-error" role="alert">${h(failure)}</div>`:''}${s.error?`<div class="notice amber">${h(s.error)}</div>`:''}
      <div class="notice"><strong>Дубай · русский и английский · запросы на услуги SignM.</strong> Вакансии, предложения исполнителей и репосты оцениваются отдельно во вкладке «Лиды → оплата». Контакт, свежесть и связь с Дубаем требуют проверки.</div><div class="notice">Чтение через общий Telegram-аккаунт сервиса. Лимиты и доступность подключения общие. Личные находки видны только здесь. Переписка ведётся через отдельно подключённый @demo_identity_3.</div>${tabNavigation()}
      ${tab==='pipeline'?window.SignMPipeline.view():tab==='sender'?window.OwnerSenderPanel.view():tab==='conversations'?window.OwnerInbox.view():tab==='sources'?sources():tab==='rules'?rules():tab==='discovery'?discoverView():tab==='history'?historyView():leads()}
      <p class="ls-footnote">Доступ к этому разделу есть только у владельца. Личная база владельца. Поиски, источники и находки хранятся отдельно от клиентской базы.</p>`;
    if(tab==='pipeline')window.SignMPipeline.mount({openConversation:openPipelineConversation});
    if(tab==='sender')window.OwnerSenderPanel.mount();
    if(tab==='conversations')window.OwnerInbox.mount();
    if(tab==='discovery')window.MarketingParser.mount();

  }
  async function openPipelineConversation(id,draft){selectTab('conversations');draw();await window.OwnerInbox.open(id,{draft});}
  function sources(){return `<div class="ls-columns"><section class="panel ls-section"><h2>Добавить источники</h2><p>До ${snapshot.source_limit||100} внешних групп или каналов. Открытые источники добавляются по ссылке после проверки доступа к сообщениям. Права администратора и добавление бота не нужны. В личном разделе используются публичные внешние сообщества.</p><form data-m-form="sources">${area('Публичные ссылки или @username — по одному на строку','references','','https://t.me/group_name')}<button class="button">Проверить и добавить</button></form>${dialogs.filter(d=>!d.managed).length?`<div class="ls-dialogs">${dialogs.filter(d=>!d.managed).map(d=>`<div><span>${h(d.title)}<small>${h(d.kind)}</small></span>${button(snapshot.sources.some(s=>s.id===d.id)?'Добавлен':'Добавить','source-add',d.id)}</div>`).join('')}</div><p class="muted small">Показаны внешние чаты аккаунта. Свои административные площадки находятся в разделе «Группы и каналы».</p>`:''}</section><section class="panel ls-section"><h2>Подключённые источники</h2>${assignment()}${snapshot.sources.length?snapshot.sources.map(s=>`<article class="ls-source"><h3>${h(s.title)}</h3><p>${s.username?'@'+h(s.username):'Закрытый источник'} · ${s.enabled?'Включён':'Отключён'}</p><small>${s.access_mode==='public'?'Публичное чтение без вступления':'Аккаунт — участник'} · Последняя проверка: ${h(stamp(s.last_scan))}<br>Последнее сообщение: ${h(stamp(s.last_message_at))}<br>Проверено новых сообщений: ${s.messages_checked||0}</small>${s.error?`<p class="ls-error">${h(s.error)}</p>`:''}<div class="ls-actions">${button(s.enabled?'Отключить':'Включить','source-toggle',s.id)}${button('Убрать из источников','source-remove',s.id)}</div></article>`).join(''):'<div class="empty"><strong>Источников пока нет</strong>Подключите Telegram-аккаунт и добавьте первую группу.</div>'}<p class="muted small">Сбор начинается с момента добавления. Недавние сообщения можно дополнительно проверить во вкладке «Анализ истории». Открытые внешние источники опрашиваются каждые 30 секунд. В чатах, где аккаунт состоит, дополнительно принимаются события новых сообщений.</p></section></div>`;}
  function rules(){const r=editing||{name:'',keywords:[],required:[],excluded:[],sources:[],enabled:true};return `<div class="ls-rules-layout"><section class="panel ls-section ls-rule-preview"><h3>Проверить текст</h3><form data-m-form="preview"><label class="ls-field">Поиск<select name="rule_id" required>${snapshot.rules.map(r=>`<option value="${r.id}" ${String(r.id)===previewDraft.ruleId?'selected':''}>${h(r.name)}</option>`).join('')}</select></label>${area('Пример сообщения','text',previewDraft.text,'Ищу яхту на выходные')}<button class="button secondary">Проверить без отправки</button></form><div id="ls-preview" role="status">${h(previewResult)}</div></section><section class="panel ls-section ls-rule-editor"><h2>${r.id?'Изменить поиск':'Новый поиск'}</h2><p>Тематики уже подготовлены. Нажмите «Изменить» у нужной, выберите источники и включите поиск.</p><form data-m-form="rule"><input type="hidden" name="id" value="${r.id||''}">${input('Название направления','name','text',r.name,'required maxlength="80"')}${area('Ключевые слова — любое совпадение','keywords',r.keywords.join('\n'),'яхта\nяхту\nкатер')}${area('Дополнительно должно встретиться одно из слов','required',r.required.join('\n'),'ищу\nнужна\nарендовать')}${area('Исключения — ни одного совпадения','excluded',r.excluded.join('\n'),'предлагаем\nсдаём')}<label class="ls-check"><input type="checkbox" name="demand_only" ${r.demand_only?'checked':''}> Фильтровать предложения продавцов и поиск работы</label><p class="muted small">Дополнительные правила проверяют связь ключа со словами спроса в одном предложении. Это не ИИ: спорное сообщение можно проверить в блоке «Проверить текст». Изменения применяются к новым сообщениям и анализу истории.</p><label class="ls-check"><input type="checkbox" name="substring" ${r.substring?'checked':''}> Искать часть слова (например, «яхт» найдёт «яхта» и «яхту»)</label><label class="ls-check"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}> Поиск включён</label><fieldset><legend>Где искать</legend>${snapshot.sources.length?snapshot.sources.map(s=>`<label class="ls-check"><input type="checkbox" name="sources" value="${s.id}" ${r.sources.includes(s.id)?'checked':''}> ${h(s.title)}${s.enabled?'':' (источник отключён)'}</label>`).join(''):'Сначала добавьте источники.'}</fieldset><div class="ls-actions"><button class="button">Сохранить поиск</button>${r.id?button('Отменить редактирование','rule-new'):''}</div></form><p class="muted small">По одной фразе на строку. Регистр и «ё/е» не учитываются. Без режима части слова совпадение ищется по целым словам; синонимы задаются явно.</p></section><section class="panel ls-section ls-rule-list"><h2>Ваши поиски</h2>${snapshot.rules.length?snapshot.rules.map(r=>`<article class="ls-source"><h3>${h(r.name)}</h3><p>${r.sources.length?(r.enabled?'Включён':'Остановлен'):'Нужно выбрать источники'} · ${r.sources.length} источников</p><p class="ls-keywords">${r.keywords.map(h).join(' · ')}</p><div class="ls-actions">${button('Изменить','rule-edit',r.id)}${r.discovery_queries?button('Подобрать площадки','discover-topic',r.id):''}${button(r.enabled?'Остановить':'Включить','rule-toggle',r.id)}</div></article>`).join(''):'<div class="empty"><strong>Создайте первый поиск</strong>Можно настроить до 25 направлений.</div>'}</section></div>`;}
  function leads(){const s=snapshot;return `<section class="panel ls-section"><div class="panel-head"><div><h2>Найденные запросы</h2>${leadContact==='telegram_author'?`<p class="small muted">Показаны только личные авторы Telegram. Записи без подтверждённого контакта: ${s.contact_counts?.missing_contact||0}; заказы бирж: ${s.contact_counts?.marketplace_task||0}. Их можно открыть через фильтр контакта.</p>`:''}<p>Показано ${s.leads.length} из ${s.filtered_total??s.total} по выбранным фильтрам<br>Проверено новых сообщений с включения счётчика: ${s.sources.reduce((n,x)=>n+(x.messages_checked||0),0)}</p></div>${button('Настроить поиск','tab','rules')}</div><label class="ls-field">Статус находки<select data-m-state>${[['new','Новые'],['working','В работе'],['rejected','Не подходят'],['all','Все статусы']].map(([v,n])=>`<option value="${v}" ${leadStatus===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="ls-field">Контакт<select data-m-contact>${[['telegram_author','Личный автор в Telegram'],['marketplace_task','Заказы со ссылкой на биржу'],['missing_contact','Без проверенного контакта'],['contacted_dialogue','Ранее начатая переписка'],['all','Все записи, включая исключённые']].map(([v,n])=>`<option value="${v}" ${leadContact===v?'selected':''}>${n} · ${v==='all'?s.total:(s.contact_counts?.[v]||0)}</option>`).join('')}</select></label><p class="small muted">Исходные сообщения и статусы сохранены. Фильтр скрывает репосты без контакта; переключение на «Все записи» возвращает полный список. Личный автор ещё не означает подтверждённый заказ.</p><label class="ls-field">Тематика<select data-m-topic><option value="all">Все тематики</option>${s.rules.map(r=>`<option value="${r.id}" ${String(r.id)===leadTopic?'selected':''}>${h(r.name)}</option>`).join('')}</select></label>${!s.leads.filter(l=>leadTopic==='all'||l.matches.some(m=>String(m.id)===leadTopic)).length?`<div class="empty"><strong>${s.connection!=='connected'?'Общее подключение недоступно':'По выбранным фильтрам находок нет'}</strong>${s.connection!=='connected'?'Проверьте общее подключение в клиентском лидсканере.':'Новые совпадения появятся здесь. Чтобы проверить уже опубликованные сообщения, откройте «Анализ истории».'}</div>`:s.leads.filter(l=>leadTopic==='all'||l.matches.some(m=>String(m.id)===leadTopic)).map(l=>`<article class="ls-lead"><div class="ls-lead-head"><strong>${h(l.source_title||l.chat_id)}</strong><time>${h(stamp(l.created))}</time></div><p class="muted">${h(l.author)}${l.origin==='history'?' · Найдено в истории':''}</p>${l.matches_current_rules===false?'<p class="notice amber small">Сохранено по прежним настройкам. По текущим правилам совпадения нет.</p>':''}<div class="notice small">${h(l.contact_readiness?.reason||'Контакт требует проверки')}</div><p class="ls-message">${h(l.text)}</p><p class="ls-keywords">${l.matches.map(m=>h(m.name)+' · '+m.keywords.map(h).join(', ')).join(' / ')}</p><div class="ls-actions">${l.link?`<a class="button secondary" href="${h(l.link)}" target="_blank" rel="noopener noreferrer">Открыть сообщение</a>`:''}${['telegram_author','contacted_dialogue'].includes(l.contact_readiness?.kind)?button('Обсудить с автором','conversation',l.id):''}${l.contact_readiness?.task_url?`<a class="button secondary" href="${h(l.contact_readiness.task_url)}" target="_blank" rel="noopener noreferrer">Заказ на бирже</a>`:''}${button('Лид → оплата','pipeline-open',l.id)}${button('История проверки контакта','contact-history',l.id)}<label>Статус <select data-m-status="${l.id}">${[['new','Новый'],['working','В работе'],['rejected','Не подходит']].map(([v,t])=>`<option value="${v}" ${l.status===v?'selected':''}>${t}</option>`).join('')}</select></label><small>${h({sent:'Уведомление отправлено',pending:'Уведомление в очереди',failed:'Ошибка доставки',cancelled:'Доставка отменена'}[l.delivery]||'Сохранено в панели')}</small></div>${l.delivery_error?`<p class="ls-error">${h(l.delivery_error)}</p>`:''}${l.delivery==='failed'&&l.status!=='rejected'?button('Повторить доставку','retry-notification',l.id):''}</article>`).join('')}<div class="ls-actions">${leadOffset?button('Предыдущие находки','leads-page',Math.max(0,leadOffset-(s.page_size||50))):''}${s.next_offset!==null&&s.next_offset!==undefined?button('Следующие находки','leads-page',s.next_offset):''}</div></section>`;}
  function historyView(){const j=snapshot.history;const labels={running:'Анализ идёт',completed:'Анализ завершён',partial:'Анализ завершён частично',cancelled:'Анализ остановлен',interrupted:'Анализ прерван'};return `<section class="panel ls-section"><h2>Проверка недавних сообщений</h2><p>Обычный сканер читает новые сообщения после подключения источника. Здесь можно проверить доступную историю всех включённых источников, увидеть причины отсева и сохранить совпадения.</p><form data-m-form="history"><div class="ls-columns"><label class="ls-field">Период<select name="days"><option value="1">Последние сутки</option><option value="3" selected>Последние 3 дня</option><option value="7">Последние 7 дней</option></select></label><label class="ls-field">До сообщений на источник<select name="limit"><option value="500">500</option><option value="1000">1 000</option><option value="2000">2 000</option></select></label></div><label class="ls-field">Действие<select name="mode"><option value="preview">Только анализ и статистика</option><option value="import">Сохранить совпадения в «Находки»</option></select></label><button class="button" ${j?.state==='running'?'disabled':''}>Проверить историю</button></form><p class="muted small">Используются включённые тематики каждого источника. Исторические находки сохраняются с исходной датой, без массовой отправки уведомлений. Повторы не добавляются. При достижении лимита проверяется только часть истории.</p>${j?`<div class="notice" role="status"><strong>${h(labels[j.state]||j.state)}</strong><p>Источников: ${j.done} из ${j.total}. Прочитано: ${j.read}. Совпадений по правилам: ${j.matched}. Сохранено новых: ${j.imported}. Повторов / уже сохранённых: ${j.duplicate}.</p><p>Без ключей: ${j.no_keywords}; без слов спроса: ${j.no_intent}; по исключениям: ${j.excluded}; без текста / исходящие: ${j.skipped}.</p><p>Период: ${j.days} дн. · до ${j.limit} сообщений на источник · ${h(stamp(j.updated))}</p>${j.state==='running'?button('Остановить анализ','history-stop'):''}${j.error?`<p class="ls-error">${h(j.error)}</p>`:''}</div><div class="ls-history-table"><table><thead><tr><th>Источник</th><th>Прочитано</th><th>По тематике</th><th>Совпадения</th><th>Результат</th></tr></thead><tbody>${j.sources.map(r=>`<tr><td>${h(r.title)}</td><td>${r.read}</td><td>${r.topic_hits}</td><td>${r.matched}</td><td>${h(r.error||(r.capped?'Достигнут лимит сообщений':'Проверен'))}</td></tr>`).join('')}</tbody></table></div>${button('Открыть находки','tab','leads')}`:'<div class="empty"><strong>История ещё не проверялась</strong>Начните с трёх дней и 500 сообщений на источник.</div>'}</section>`;}
  function assignment(){return snapshot.sources.length?`<details><summary>Распределить источники по тематикам</summary><form data-m-form="assign"><fieldset><legend>Источники</legend>${snapshot.sources.filter(s=>s.enabled).map(s=>`<label class="ls-check"><input type="checkbox" name="assign_sources" value="${s.id}">${h(s.title)}</label>`).join('')}</fieldset><fieldset><legend>Тематики</legend>${snapshot.rules.map(r=>`<label class="ls-check"><input type="checkbox" name="assign_rules" value="${r.id}">${h(r.name)}</label>`).join('')}</fieldset><button class="button">Привязать и включить выбранные поиски</button></form><p>Общий запуск сканера включается отдельно кнопкой «Запустить поиск».</p></details>`:'';}
  function discoverView(){return window.MarketingParser.view(snapshot);}
  async function perform(fn,el,refreshAfter=true){if(el)el.disabled=true;failure='';try{await fn();if(refreshAfter)await refresh();else document.querySelector('#marketing-scanner .ls-action-error')?.remove();}catch(e){failure=e.message;const box=document.querySelector('#marketing-scanner');if(box){let error=box.querySelector('.ls-action-error');if(!error){error=document.createElement('div');error.className='ls-error ls-action-error';error.setAttribute('role','alert');box.prepend(error);}error.textContent=failure;error.scrollIntoView({block:'nearest'});}}finally{if(el)el.disabled=false;}}
  document.addEventListener('click',e=>{const b=e.target.closest('[data-m-action]');if(!b||!document.querySelector('#marketing-scanner'))return;const a=b.dataset.mAction,id=Number(b.dataset.id);
    if(a==='contact-history'||a==='contact-history-retry'){showContactHistory(id||contactHistoryId);return;}
    if(a==='contact-history-close'){contactDialog?.close();return;}
    if(a==='pipeline-open'){selectTab('pipeline');draw();window.SignMPipeline.open(id);return;}
    if(a==='conversation'){selectTab('conversations');draw();window.OwnerInbox.open(id);return;}
    if(a==='tab'){selectTab(b.dataset.id);failure='';mount();return;}
    if(a==='rule-edit'){editing=snapshot.rules.find(x=>x.id===id);draw();document.querySelector('[data-m-form="rule"]')?.scrollIntoView({block:'start'});return;}
    if(a==='rule-new'){editing=null;draw();return;}
    if(a==='discover-topic'){const r=snapshot.rules.find(x=>x.id===id);selectTab('discovery');draw();window.MarketingParser.preset(r);return;}
    perform(async()=>{
      if(a==='refresh')return;
      if(a==='leads-page')leadOffset=id;
      if(a==='history-stop')await api('history/stop',{});
      if(a==='running')await api('running',{enabled:!snapshot.running});
      if(a==='source-add')await api('sources',{reference:String(id)});
      if(a==='source-toggle')await api('sources/'+id,{enabled:!snapshot.sources.find(s=>s.id===id).enabled});
      if(a==='source-remove')await api('sources/'+id+'/remove',{});
      if(a==='rule-toggle')await api('rules/'+id,{enabled:!snapshot.rules.find(r=>r.id===id).enabled});
    },b);
  });
  document.addEventListener('submit',e=>{const f=e.target;if(!f.matches('[data-m-form]'))return;e.preventDefault();const d=new FormData(f),v=n=>String(d.get(n)||'').trim();perform(async()=>{
    switch(f.dataset.mForm){
      case 'history':await api('history',{days:Number(v('days')),limit:Number(v('limit')),mode:v('mode')});break;
      case 'assign':await api('assign',{sources:d.getAll('assign_sources').map(Number),rules:d.getAll('assign_rules').map(Number)});break;
      case 'sources':{const refs=[...new Set(v('references').split(/\r?\n/).map(s=>s.trim()).filter(Boolean))];if(!refs.length)throw Error('Введите хотя бы один источник.');if(refs.length>(snapshot.source_limit||100))throw Error('Добавляйте не более '+(snapshot.source_limit||100)+' источников за раз.');const bad=[];for(const ref of refs){try{await api('sources',{reference:ref});}catch(e){bad.push(ref+': '+e.message);}}if(bad.length){await refresh();throw Error(bad.join('\n'));}break;}
      case 'rule':await api('rules',{id:v('id')?Number(v('id')):null,name:v('name'),sources:d.getAll('sources').map(Number),keywords:v('keywords'),required:v('required'),excluded:v('excluded'),substring:d.has('substring'),demand_only:d.has('demand_only'),enabled:d.has('enabled')});editing=null;break;
      case 'preview':{const r=await api('preview',{rule_id:Number(v('rule_id')),text:v('text')});previewResult=(r.matched?'Совпадение: '+r.keywords.join(', '):'Совпадений нет')+'. '+r.note;document.querySelector('#ls-preview').textContent=previewResult;return;}
    }
    if(['credentials','code','password'].includes(f.dataset.mForm))f.reset();
  },f.querySelector('button[type="submit"],button:not([type])'),f.dataset.mForm!=='preview');});
  document.addEventListener('input',e=>{const f=e.target.closest('[data-m-form="preview"]');if(!f)return;previewDraft={ruleId:f.elements.rule_id.value,text:f.elements.text.value};previewResult='';const result=document.querySelector('#ls-preview');if(result)result.textContent='';});
  document.addEventListener('change',e=>{if(e.target.matches('[data-m-contact]')){leadContact=e.target.value;leadOffset=0;refresh();return;}if(e.target.matches('[data-m-topic]')){leadTopic=e.target.value;leadOffset=0;refresh();return;}if(e.target.matches('[data-m-state]')){leadStatus=e.target.value;leadOffset=0;refresh();return;}if(e.target.matches('[data-m-status]'))perform(()=>api('leads/'+e.target.dataset.mStatus,{status:e.target.value}),e.target);});
  setInterval(()=>{if(!contactHistoryOpen()&&document.visibilityState!=='hidden'&&document.querySelector('#marketing-scanner')&&['leads','history'].includes(tab)&&!document.activeElement?.matches('input,select,textarea')&&!loading)refresh(false);},15000);
  return {view,mount};
})();
